import unittest

import e2e_feature


class E2EFeatureTest(unittest.TestCase):
    def test_answer_is_42(self):
        self.assertEqual(e2e_feature.answer(), 42)

    def test_label_prefixes(self):
        self.assertEqual(e2e_feature.label("x"), "e2e:x")

    def test_label_empty(self):
        self.assertEqual(e2e_feature.label(""), "e2e:")


if __name__ == "__main__":
    unittest.main()

